// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 value, uint256 unlockTime) public {
        // Bound value to a reasonable range that can trigger overflow
        value = bound(value, 0, type(uint256).max);
        // Admissible unlockTime: any future or past timestamp
        unlockTime = bound(unlockTime, 0, type(uint256).max);

        // Record total contributions by summing all Put calls
        uint256 totalContributed;

        // Deploy an adversarial helper: a re-entrant attacker that calls Put during Collect
        // The bug manifests via overflow on balance addition; we just need to call Put.
        address actor = address(0x1234);
        vm.deal(actor, value);
        vm.prank(actor);
        c.Put{value: value}(unlockTime);

        // After Put, the user's balance should equal the amount sent.
        // Due to overflow, the buggy version may record a smaller balance.
        (uint256 recordedUnlockTime, uint256 recordedBalance) = c.Acc(actor);

        // Invariant: accurate balance reflects all Ether sent and not withdrawn
        // For a single Put, recordedBalance must equal the msg.value sent.
        assertTrue(recordedBalance == value);
    }
}

