pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 amount, uint256 unlockTime) public {
        // restrict amount to a range where overflow is possible but not guaranteed
        uint256 maxBalance = type(uint256).max;
        vm.assume(amount > 0 && amount <= maxBalance);
        // fund the test contract and call Put
        vm.deal(address(this), amount);
        c.Put{value: amount}(unlockTime);
        // after Put, the recorded balance for the caller must be at least the amount sent
        // (original invariant: acc.balance >= amount, since acc.balance = old + amount and old >= 0)
        // without overflow check, acc.balance can overflow and become less than amount
        (uint recordedUnlockTime, uint recordedBalance) = c.Acc(address(this));
        assertTrue(recordedBalance >= amount);
    }
}

