import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address sender, uint96 amount, uint32 unlockTime) public {
        vm.assume(sender != address(0) && sender != address(this));
        amount = uint96(bound(amount, 1 ether, 10 ether));
        unlockTime = uint32(bound(unlockTime, uint32(block.timestamp) + 1, type(uint32).max));

        // Fund and execute Put
        vm.deal(sender, amount);
        vm.prank(sender);
        c.Put{value: amount}(unlockTime);

        // Advance time to just before the expected unlock
        vm.warp(uint256(unlockTime) - 1);

        // Try to Collect the full balance, which should fail because unlockTime has not been reached
        vm.prank(sender);
        try c.Collect(amount) {
            // In the reference contract, Collect should revert because block.timestamp < unlockTime
            // If execution reaches here, the Collect succeeded — this indicates the buggy version
            assertTrue(false);
        } catch {
            // Reference contract reverts as expected; buggy version may skip this catch
            assertTrue(true);
        }
    }
}

