pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 unlockTime, uint256 amount) public {
        // admissible domain: amount > 0 and >= MinSum, and we need an unlockTime in the future so we can test the condition
        amount = bound(amount, 1 ether, 1000 ether);
        unlockTime = bound(unlockTime, block.timestamp + 1, type(uint256).max);

        address user = address(0x1234);
        vm.deal(user, amount);
        vm.startPrank(user);
        c.Put{value: amount}(unlockTime);
        vm.stopPrank();

        // warp to exactly unlockTime (timestamp NOT > unlockTime)
        vm.warp(unlockTime);

        // attempt Collect
        bool ok;
        vm.startPrank(user);
        try c.Collect(amount) {
            ok = true;
        } catch {
            ok = false;
        }
        vm.stopPrank();

        // Reference P: Collect MUST REVERT because timestamp is NOT strictly > unlockTime
        assertTrue(!ok, "Collect should revert when timestamp <= unlockTime");
    }
}

