        // Restrict to amounts that can be deposited and later withdrawn above MinSum
        vm.assume(am >= 1 ether && am <= 1000 ether);
        vm.assume(unlockTime >= 0 && unlockTime <= type(uint48).max);
        address actor = address(0x1234);
        vm.deal(actor, 2 ether);
        // Deposit with a future unlockTime
        vm.warp(1000);
        vm.prank(actor);
        c.Put{value: 1 ether}(unlockTime + 1000);
        // Ensure current timestamp is still before the unlock time
        vm.warp(unlockTime);
        require(unlockTime < unlockTime + 1000, "warp must be <= unlock");
        vm.prank(actor);
        bool ok;
        try c.Collect(am) { ok = true; } catch { ok = false; }
        // After a successful Collect, the balance decreases; but if timestamp <= unlockTime,
        // the reference C must revert. The buggy version may succeed, so assert exactly revert.
        assertTrue(!ok);
    }
}

