pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 unlockTime, uint256 amount, uint256 collectAmt) public {
        // Keep amounts in admissible range
        vm.assume(amount >= 1 ether);
        vm.assume(amount <= 1000 ether);
        vm.assume(collectAmt >= 1 ether);
        vm.assume(collectAmt <= amount);

        address caller = address(0x1000);
        vm.deal(caller, amount);

        // Set block.timestamp to a fixed time T
        uint256 T = 1000;
        vm.warp(T);

        // Put with unlockTime in the future (T+10)
        vm.prank(caller);
        c.Put{value: amount}(T + 10);

        // Advance time so block.timestamp equals unlockTime (or less)
        // Test when block.timestamp <= unlockTime
        vm.warp(T + 5); // block.timestamp < unlockTime

        uint256 balanceBefore = c.Acc(caller).balance;

        // Try Collect
        bool ok;
        try c.Collect(collectAmt) { ok = true; } catch { ok = false; }

        uint256 balanceAfter = c.Acc(caller).balance;

        // Assert: if Collect succeeded and balance decreased, then block.timestamp must be > unlockTime
        // Here block.timestamp (T+5) <= unlockTime (T+10), so balance must NOT decrease
        assertTrue(!ok || balanceAfter == balanceBefore);
    }
}

