pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    uint256 constant MinSum = 1 ether;

    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(uint256 _unlockTime, uint128 putAmount, uint128 collectAmount, uint256 collectDelay) public {
        // Restrict domain: unlockTime can be any representative past or future timestamp.
        // block.timestamp is 1 (default in Foundry). Allow past (<=1) and future (>1) values.
        vm.assume(_unlockTime >= 0 && _unlockTime <= type(uint64).max);
        // Put amount must not overflow balance and must be >0 to ensure balance building.
        vm.assume(putAmount > 0 && putAmount <= type(uint128).max);
        // Collect amount must be <= balance after put and >= MinSum.
        vm.assume(collectAmount >= MinSum && collectAmount <= type(uint128).max);
        vm.assume(collectAmount <= putAmount);
        // Delay before Collect attempt: 0 (immediate) up to some bound to test time-lock behaviour.
        vm.assume(collectDelay <= 365 days);

        address caller = address(0x1000);
        vm.deal(caller, putAmount);
        vm.startPrank(caller);

        // Perform Put with the fuzzed unlockTime and amount.
        c.Put{value: putAmount}(_unlockTime);
        vm.stopPrank();

        // Warp to collect time: Put was at timestamp 1 (default), collect at 1 + collectDelay.
        vm.warp(1 + collectDelay);

        // Try to Collect. We need to check whether the call reverts.
        vm.startPrank(caller);
        bool success;
        try c.Collect(collectAmount) { success = true; } catch { success = false; }
        vm.stopPrank();

        // General rule on reference C:
        // If _unlockTime is in the past (<= block.timestamp of Put, which is 1),
        // the reference sets unlockTime to block.timestamp (1). Therefore,
        // block.timestamp of the Collect attempt (1 + collectDelay) must be > 1 for Collect to succeed.
        // So if _unlockTime <= 1 and collectDelay == 0 (timestamp 1), Collect MUST revert.
        // The bug stores _unlockTime directly (<=1). With collectDelay == 0, block.timestamp is 1,
        // and if _unlockTime <= 1, block.timestamp > _unlockTime holds for _unlockTime < 1, so Collect succeeds.
        // The rule: For _unlockTime <= 1 and collectDelay == 0, the reference reverts; the bug succeeds.
        // But as a general assertion that passes for all inputs on reference:
        // If _unlockTime <= 1 and collectDelay == 0, then success must be false.
        // The fuzzer will try combinations, and on the reference this holds always.
        // On the buggy version, when _unlockTime < 1, success becomes true, failing the assertion.
        if (_unlockTime <= 1 && collectDelay == 0) {
            assertTrue(!success);
        } else {
            // For other parameter combinations, the fuzzer may explore but we must avoid failing the reference.
            // The reference always obeys rules, so we just assert true here to keep the test valid for all paths.
            assertTrue(true);
        }
    }
}

