    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 _am, uint32 _warp) public {
        // Admissible domain: must meet Collect conditions (balance >= MinSum, balance >= _am, timestamp > unlockTime)
        uint256 deposit = _am + 1 ether;
        vm.assume(deposit >= _am);
        vm.deal(address(this), deposit);
        c.Put{value: deposit}(uint256(_warp) + 1);
        vm.warp(uint256(_warp) + 2);
        uint256 balBefore = address(this).balance;
        bool ok;
        try c.Collect(_am) { ok = true; } catch { ok = false; }
        if (ok) {
            uint256 balAfter = address(this).balance;
            // For reference, the caller's Ether balance must increase by exactly _am.
            assertTrue(balAfter - balBefore == _am);
        }
    }
}
